// Synthetic replica of react-native-mmkv@3 sources. The published package points
// its "react-native" / exports condition at TypeScript whose MMKV constructor
// reaches into a JSI-installed native module. We resolve the native installer off
// the React Native default export so the bundle resolves cleanly; the installer
// is unavailable at build time because the native MMKV TurboModule/JSI binding is
// only registered on a device, so an instance backed by real storage cannot be
// created from a bundler build.
import ReactNative from "react-native";

const MmkvPlatformContext =
  (ReactNative as { TurboModuleRegistry?: { get(name: string): unknown } }).TurboModuleRegistry?.get(
    "MmkvPlatformContext",
  ) ?? null;

export const MMKV_OK = "MMKV_OK";

export type Configuration = {
  id?: string;
  encryptionKey?: string;
};

export class MMKV {
  private readonly store = new Map<string, string | number | boolean>();

  // On a device the JSI bindings install onto this handle; off-device the
  // platform context is null, so it stays null and the in-memory fallback below
  // never reaches native storage.
  private readonly nativeInstance: unknown = MmkvPlatformContext;

  constructor(public readonly configuration: Configuration = {}) {}

  set(key: string, value: string | number | boolean): void {
    this.store.set(key, value);
  }

  getString(key: string): string | undefined {
    const value = this.store.get(key);
    return typeof value === "string" ? value : undefined;
  }

  contains(key: string): boolean {
    return this.store.has(key);
  }

  delete(key: string): void {
    this.store.delete(key);
  }
}
